import type { CardsFile, CardsFileCard } from "../catalog";

/**
 * Builders for test data in the same shape as `data/tarjetas.json`
 * (Spanish keys, as generated by `scripts/calcular.py --json`).
 */

export const goalsFixture: CardsFile["objetivos"] = {
  diario: { kcal: 1900, prot: 180, carb: 175, grasa: 56, fibra_min: 30 },
  tolerancia: { kcal_pct: 5, macro_g: 5 },
  momentos: {
    desayuno: { kcal: 400, prot: 35, carb: 45, grasa: 9 },
    almuerzo: { kcal: 600, prot: 55, carb: 55, grasa: 18 },
    merienda: { kcal: 300, prot: 35, carb: 25, grasa: 7 },
    cena: { kcal: 600, prot: 55, carb: 50, grasa: 22 },
  },
};

let nextId = 1;

export function cardFixture(overrides: Partial<CardsFileCard> = {}): CardsFileCard {
  const id = overrides.id ?? `card-${nextId++}`;
  return {
    id,
    momento: "desayuno",
    tipo: "dulce",
    nombre: `Tarjeta ${id}`,
    ingredientes: [{ id: "avena", g: 40, nombre: "Copos de avena", categoria: "cereal" }],
    preparacion: "Mezclar y calentar.",
    nutricion: { kcal: 400, prot: 35, carb: 45, grasa: 9, fibra: 5 },
    ...overrides,
  };
}

export function cardsFileFixture(cards: CardsFileCard[]): CardsFile {
  return { objetivos: goalsFixture, tarjetas: cards };
}
